class AsyncNodeDeviceProxy:
    """The operations on one node device, with it filled in."""

    def __init__(self, client: AsyncLibvirtClient, node_device: NodeDeviceRef) -> None:
        """Create the proxy.

        :param client: the client the operations go through.
        :param node_device: the node device they act on.
        """
        self._client = client
        self._reference = node_device

    async def lookup(self) -> Device:
        """Return a device of the host.

        :returns: the device and its capabilities.
        :raises NoNodeDeviceError: if there is no such device.
        """
        return await self._client.lookup_node_device(self._reference)

    async def destroy(self) -> None:
        """Remove a virtual device created with ``create_node_device``."""
        return await self._client.destroy_node_device(self._reference)

    async def get_parent(self) -> str | None:
        """Return the name of the parent of a host device.

        :returns: the parent's name, or ``None`` if it has none.
        """
        return await self._client.get_node_device_parent(self._reference)

    async def list_capabilities(self, *, max_names: int = 256) -> list[str]:
        """List the capabilities of a host device.

        :param max_names: how many names to ask for at most.
        :returns: the capability names, e.g. ``pci``, ``net``.
        """
        return await self._client.list_node_device_capabilities(
            self._reference, max_names=max_names
        )

    async def detach(self, driver: str | None = None, *, flags: int = 0) -> None:
        """Detach a device from its host driver, to give it to a guest.

        :param driver: the driver to bind it to (``vfio``); ``None`` for the default.
        :param flags: reserved, 0.
        """
        return await self._client.detach_node_device(
            self._reference, driver, flags=flags
        )

    async def reattach(self) -> None:
        """Give a device back to its host driver."""
        return await self._client.reattach_node_device(self._reference)

    async def reset(self) -> None:
        """Reset a host device."""
        return await self._client.reset_node_device(self._reference)

    async def undefine(self, *, flags: int = 0) -> None:
        """Remove the stored definition of a mediated device.

        :param flags: reserved, 0.
        """
        return await self._client.undefine_node_device(self._reference, flags=flags)

    async def start(self, *, flags: int = 0) -> None:
        """Start a defined mediated device.

        :param flags: reserved, 0.
        """
        return await self._client.start_node_device(self._reference, flags=flags)

    async def get_autostart(self) -> bool:
        """Tell whether a mediated device starts at host boot.

        :returns: ``True`` if it does.
        """
        return await self._client.get_node_device_autostart(self._reference)

    async def set_autostart(self, enabled: bool) -> None:
        """Choose whether a mediated device starts at host boot.

        :param enabled: ``True`` to start it at boot.
        """
        return await self._client.set_node_device_autostart(self._reference, enabled)

    async def is_active(self) -> bool:
        """Tell whether a mediated device is started.

        :returns: ``True`` if it is active.
        """
        return await self._client.is_node_device_active(self._reference)

    async def is_persistent(self) -> bool:
        """Tell whether a mediated device has a stored definition.

        :returns: ``True`` if persistent.
        """
        return await self._client.is_node_device_persistent(self._reference)

    async def update(self, definition: Device | str, *, flags: int = 0) -> None:
        """Change the definition of a mediated device.

        :param definition: the new description, as a model or XML.
        :param flags: ``virNodeDeviceUpdateFlags``: 1 affect the running device.
        """
        return await self._client.update_node_device(
            self._reference, definition, flags=flags
        )
